export const T_AIR = 0;
export const T_SOLID = 1;
export const T_SLICK = 2; // plein, non accrochable
export const T_SPIKE = 3;
export const T_BOUNCE = 4; // tremplin : plein, non accrochable, relance vers le haut quand on s'y pose

/** Vitesse verticale (px/s) donnée par un tremplin : ~19 tuiles de montée en chute libre. */
export const BOUNCE_SPEED = 1500;

/** Inset de la hitbox des pics (en px) pour être un peu tolérant aux frôlements. */
export const SPIKE_INSET = 6;

export interface EnemySpawn {
  x: number; // centre, px
  y: number;
  w: number;
  h: number;
  patrol: boolean;
}

export interface ZoneLabel {
  name: string;
  x: number; // tuiles
  y: number;
}

/** Objectif du niveau : nettoyer le stock d'ennemis, ou atteindre l'arrivée le plus vite possible. */
export type LevelMode = 'kills' | 'race';

/** Zone d'arrivée, en px (rectangle englobant les tuiles `F`). */
export interface GoalRect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface Level {
  name: string;
  mode: LevelMode;
  subtitle: string;
  width: number; // en tuiles
  height: number;
  tiles: Uint8Array; // width*height, indexé [y*width + x]
  spawnX: number; // px, centre du joueur
  spawnY: number;
  enemies: readonly EnemySpawn[];
  labels: readonly ZoneLabel[];
  /** Non nul uniquement en mode 'race'. */
  goal: GoalRect | null;
  /**
   * Panneaux écrits dans le décor (le tutoriel). Rendu seulement : ni la sim ni l'empreinte de la
   * carte ne les lisent.
   */
  signs?: readonly LevelSign[];
  /** Ateliers du tutoriel (colonne de départ en px, nom) : le HUD dit où l'on en est. Rendu seulement. */
  stations?: readonly { x: number; name: string }[];
}

/** Un panneau peint dans le décor : coin haut-gauche en tuiles, un titre (facultatif) et des lignes. */
export interface LevelSign {
  x: number;
  y: number;
  title: string;
  lines: readonly string[];
}

/** Bornes des panneaux d'une carte perso (éditeur, workshop). */
export const SIGN_MAX = 40;
export const SIGN_TITLE_MAX = 24;
export const SIGN_LINES_MAX = 6;
export const SIGN_LINE_MAX = 48;

function cleanSignText(raw: unknown, max: number): string {
  if (typeof raw !== 'string') return '';
  return [...raw.normalize('NFC').replace(/[\p{C}]/gu, '').replace(/\s+/g, ' ').trim()].slice(0, max).join('').trimEnd();
}

/**
 * Panneaux reçus (stockage, import, réseau) remis en forme : coin dans la carte (w × h tuiles),
 * textes sans caractères de contrôle et bornés, panneaux vides retirés. Jamais d'exception.
 */
export function sanitizeSigns(raw: unknown, w: number, h: number): LevelSign[] {
  if (!Array.isArray(raw)) return [];
  const out: LevelSign[] = [];
  for (const s of raw) {
    if (out.length >= SIGN_MAX) break;
    const o = s as Partial<LevelSign> | null;
    if (!o || typeof o !== 'object') continue;
    const x = Math.round(Number(o.x));
    const y = Math.round(Number(o.y));
    if (!Number.isFinite(x) || !Number.isFinite(y) || x < 0 || y < 0 || x >= w || y >= h) continue;
    const title = cleanSignText(o.title, SIGN_TITLE_MAX);
    const lines = (Array.isArray(o.lines) ? o.lines : []).slice(0, SIGN_LINES_MAX).map((l) => cleanSignText(l, SIGN_LINE_MAX));
    while (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
    if (!title && lines.length === 0) continue;
    out.push({ x, y, title, lines });
  }
  return out;
}

